import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Dhf_H6O0.js";const n="/mbit-mcpo-proxy-download/guide/images/settings-page.png",m=JSON.parse('{"title":"Gateway & Docker Settings","description":"","frontmatter":{},"headers":[],"relativePath":"settings/gateway-docker.md","filePath":"settings/gateway-docker.md"}'),i={name:"settings/gateway-docker.md"};function s(l,t,g,c,h,d){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="gateway-docker-settings" tabindex="-1">Gateway &amp; Docker Settings <a class="header-anchor" href="#gateway-docker-settings" aria-label="Permalink to &quot;Gateway &amp; Docker Settings&quot;">​</a></h1><p>The Settings page lets you configure how the gateway runs. Click <strong>Settings</strong> in the sidebar to access it.</p><p><img src="'+n+'" alt="Settings page — Gateway &amp; Docker section"></p><h2 id="http-port" tabindex="-1">HTTP port <a class="header-anchor" href="#http-port" aria-label="Permalink to &quot;HTTP port&quot;">​</a></h2><p>The port the gateway listens on. Default: <strong>8000</strong>.</p><ul><li>All server URLs use this port (e.g., <code>http://localhost:8000/telecontext</code>).</li><li>Change it if port 8000 is already used by another application.</li><li>Valid range: 1024–65535.</li><li>Changing the port <strong>automatically restarts</strong> the gateway container.</li></ul><h2 id="memory-limit" tabindex="-1">Memory limit <a class="header-anchor" href="#memory-limit" aria-label="Permalink to &quot;Memory limit&quot;">​</a></h2><p>Control how much RAM the Docker container can use.</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>No limit — the container can use as much memory as Docker allows</td></tr><tr><td><strong>64</strong> or higher</td><td>Hard limit in MiB (minimum: 64 MiB)</td></tr></tbody></table><p>Increase this if you&#39;re running resource-intensive MCP servers (like Local RAG with large documents). Requires <strong>Apply &amp; Restart</strong>.</p><h2 id="cpu-limit" tabindex="-1">CPU limit <a class="header-anchor" href="#cpu-limit" aria-label="Permalink to &quot;CPU limit&quot;">​</a></h2><p>Control how many CPU cores the container can use.</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>No limit — uses all available cores</td></tr><tr><td><strong>0.5</strong>, <strong>1</strong>, <strong>1.5</strong>, etc.</td><td>Fractional core limit</td></tr></tbody></table><p>Useful if you want to keep CPU usage down while running other applications. Requires <strong>Apply &amp; Restart</strong>.</p><h2 id="saving-changes" tabindex="-1">Saving changes <a class="header-anchor" href="#saving-changes" aria-label="Permalink to &quot;Saving changes&quot;">​</a></h2><p>Click <strong>Save</strong> after changing any setting. Port changes trigger an automatic restart. Memory and CPU changes require a manual <strong>Apply &amp; Restart</strong> from the Dashboard.</p>',16)])])}const u=e(i,[["render",s]]);export{m as __pageData,u as default};
